import { useState, useEffect } from 'react';
import { useHistory } from 'react-router-dom';

function ProfileDetails() {
    const userId = localStorage.getItem('userId');
    const history = useHistory();

    const [user, setUser] = useState(null);
    const [isEditing, setIsEditing] = useState(false);
    const [editForm, setEditForm] = useState({
        firstName: '',
        lastName: '',
        phoneNumber: '',
        address: '',
        postalCode: '',
        city: '',
        country: '',
        paymentPreference: ''
    });

    useEffect(() => {
        if (!userId) {
            history.push('/login');
            return;
        }
        
        // Fetch user data
        fetch(`http://localhost:3001/user/${userId}`)
            .then(res => res.json())
            .then(data => {
                setUser(data);
                setEditForm({
                    firstName: data.firstName || '',
                    lastName: data.lastName || '',
                    phoneNumber: data.phoneNumber || '',
                    address: data.address || '',
                    postalCode: data.postalCode || '',
                    city: data.city || '',
                    country: data.country || '',
                    paymentPreference: data.paymentPreference || 'Carte bancaire'
                });
            })
            .catch(err => console.error('Erreur lors de la récupération du profil', err));
    }, [userId, history]);

    const handleLogout = () => {
        localStorage.removeItem('userId');
        localStorage.removeItem('token');
        history.push('/login');
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setEditForm(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const handleSave = (e) => {
        e.preventDefault();
        fetch(`http://localhost:3001/user/${userId}`, {
            method: 'PUT',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(editForm)
        })
        .then(res => {
            if (!res.ok) throw new Error('Erreur lors de la mise à jour');
            return res.json();
        })
        .then(() => {
            setUser(prev => ({ ...prev, ...editForm }));
            setIsEditing(false);
        })
        .catch(err => console.error(err));
    };

    if (!user) return <div>Chargement du profil...</div>;

    return (
        <div style={{ padding: '20px' }}>
            <h2>Bienvenue sur votre profil !</h2>
            
            {!isEditing ? (
                <div>
                    <p>Voici vos informations personnelles :</p>
                    <ul>
                        <li>Id : {user.idUser}</li>
                        <li>Nom : {user.lastName}</li>
                        <li>Prenom : {user.firstName}</li>
                        <li>Email : {user.email}</li>
                        <li>Numéro de téléphone : {user.phoneNumber}</li>
                        <li>Adresse : {user.address}</li>
                        <li>Code postal : {user.postalCode}</li>
                        <li>Ville : {user.city}</li>
                        <li>Pays : {user.country}</li>
                        <li>Préférence de paiement : {user.paymentPreference}</li>
                    </ul>
                    <button onClick={() => setIsEditing(true)} style={{ marginRight: '10px' }}>Modifier les informations</button>
                    <button onClick={handleLogout}>Se déconnecter</button>
                </div>
            ) : (
                <form onSubmit={handleSave}>
                    <p>Modifier vos informations :</p>
                    <div style={{ marginBottom: '10px' }}>
                        <label>Nom : </label>
                        <input type="text" name="lastName" value={editForm.lastName} onChange={handleInputChange} required />
                    </div>
                    <div style={{ marginBottom: '10px' }}>
                        <label>Prénom : </label>
                        <input type="text" name="firstName" value={editForm.firstName} onChange={handleInputChange} required />
                    </div>
                    <div style={{ marginBottom: '10px' }}>
                        <label>Numéro de téléphone : </label>
                        <input type="tel" name="phoneNumber" value={editForm.phoneNumber} onChange={handleInputChange} />
                    </div>
                    <div style={{ marginBottom: '10px' }}>
                        <label>Adresse : </label>
                        <input type="text" name="address" value={editForm.address} onChange={handleInputChange} />
                    </div>
                    <div style={{ marginBottom: '10px' }}>
                        <label>Code postal : </label>
                        <input type="text" name="postalCode" value={editForm.postalCode} onChange={handleInputChange} />
                    </div>
                    <div style={{ marginBottom: '10px' }}>
                        <label>Ville : </label>
                        <input type="text" name="city" value={editForm.city} onChange={handleInputChange} />
                    </div>
                    <div style={{ marginBottom: '10px' }}>
                        <label>Pays : </label>
                        <input type="text" name="country" value={editForm.country} onChange={handleInputChange} />
                    </div>
                    <div style={{ marginBottom: '10px' }}>
                        <label>Préférence de paiement : </label>
                        <select name="paymentPreference" value={editForm.paymentPreference} onChange={handleInputChange}>
                            <option value="Carte bancaire">Carte bancaire</option>
                            <option value="Paypal">Paypal</option>
                        </select>
                    </div>
                    
                    <button type="submit" style={{ marginRight: '10px' }}>Sauvegarder</button>
                    <button type="button" onClick={() => setIsEditing(false)}>Annuler</button>
                </form>
            )}
        </div>
    );
}

export default ProfileDetails;
